import React from 'react';
import { 
  FileText, 
  ArrowUpRight, 
  Building2, 
  Check, 
  DollarSign, 
  ArrowRight 
} from 'lucide-react';
import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';

// Utility for class merging
function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

// Plan Types
